import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Magery overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/overview.md","filePath":"en/guide/magic/overview.md"}'),n={name:"en/guide/magic/overview.md"};function o(d,e,l,s,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="magery-overview" tabindex="-1">Magery overview <a class="header-anchor" href="#magery-overview" aria-label="Permalink to &quot;Magery overview&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New design not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Magery supports execution; Core Patterns supply learned spell knowledge.</li><li>Familiarity, Active Memory and compatible variants shape practical options.</li><li>Discovery continues beyond skill mastery; these mechanics remain Proposed.</li></ul><p>Magery measures execution, not automatic knowledge of every spell. Discovery, practice and preparation give two equally skilled mages different options.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>What it means</th></tr></thead><tbody><tr><td>Core Pattern</td><td>Stable learned spell identity</td></tr><tr><td>Glyph / variant</td><td>Compatible learned modification with trade-offs</td></tr><tr><td>Magery</td><td>Technical execution</td></tr><tr><td>Familiarity</td><td>Practice with a particular pattern</td></tr><tr><td>Active Memory</td><td>Limited ready loadout</td></tr></tbody></table><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Boundary</th></tr></thead><tbody><tr><td>Learn through the world</td><td>Skill thresholds alone do not teach spells</td></tr><tr><td>Prepare known patterns</td><td>Memorized is not instant casting</td></tr><tr><td>Modify spells</td><td>Bounded combinations, not unrestricted spell building</td></tr><tr><td>Reach 100</td><td>Technical mastery, not magical completion</td></tr></tbody></table><p>Rare patterns, schools, rituals, regional knowledge, grimoires, reagents and Inscription remain longer-term goals under the proposed no-ordinary-120 direction. This combat batch adds no spell numbers.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A mage may know a useful spell but still need reference time if it was not prepared for the encounter.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Learning</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory</a> · <a href="/Syrolands-Public/en/guide/magic/variants-and-glyphs.html">Variants</a> · <a href="/Syrolands-Public/en/guide/magic/meditation-and-concentration.html">Meditation</a> · <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Books and reagents</a> · <a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/en/game-design/magic.html">Full design</a></p>',14)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
